// =====================================================================
//  WELT 2 – DIE RANGLISTE – GERÜST
//  Informatik LK · Online-IDE · Algo Quest · Level 2.1 bis 2.3
//
//  Euer Dungeon-Spiel braucht eine Highscore-Liste: Wer hat die meisten
//  Punkte? Steht "Aria" schon drin? Und wie bringt man 1000 Eintraege
//  moeglichst schnell in die richtige Reihenfolge? In der Rangliste
//  baust du die Standardbausteine, drei Sortierverfahren und die
//  binaere Suche - und zaehlst mit, wie viel Arbeit sie machen.
//
//  ANLEITUNG:
//  1. Du arbeitest NUR im Abschnitt "DEIN TEIL": in der Klasse Rangliste
//     unterhalb der Linie "AB HIER ARBEITEST DU" und in der Klasse Suche.
//     Ersetze die Zeilen "// TODO Level 2.x" und die vorlaeufigen
//     return-Anweisungen durch deine Loesung. Die Kommentare ueber jeder
//     Methode sagen genau, was sie tun soll.
//
//  2. Tests starten: Oeffne den Reiter "Testrunner" und klicke auf den
//     gruenen Dreieckspfeil neben einer Testklasse (alle Tests dieses
//     Levels) oder neben einem einzelnen Test. Gruen = bestanden,
//     rot = noch nicht bestanden. Lies bei roten Tests die Meldung!
//
//  3. Die Level und ihre Testklassen:
//
//      Level  DS  Testklasse         Inhalt
//      ----------------------------------------------------------------
//      2.1    8   L21StandardTest    Standardbausteine auf der Reihung
//                                    von Eintraegen: Maximum, bester
//                                    Eintrag, Zaehlen, lineare Suche,
//                                    Durchschnitt, Duplikate
//      2.2    9   L22SortierTest     istSortiert, Selectionsort,
//                                    Insertionsort, Bubblesort,
//                                    sortiert einfuegen - die Tests
//                                    pruefen das Ergebnis UND die Zahl
//                                    der Vergleiche und Vertauschungen
//      2.3    11  L23SucheTest       lineare und binaere Suche auf
//                                    Reihungen von Ganzzahlen,
//                                    Durchlaeufe zaehlen, Einfuegeposition
//
//     In jedem Level gibt es drei Stufen. Du erkennst sie am Anfang des
//     Testnamens:
//          basis_...         Basis
//          erweiterung_...   Erweiterung
//          experte_...       Experte
//     Eine Stufe ist geschafft, wenn ALLE Tests mit diesem Anfang gruen
//     sind. Ein paar Tests sind schon am Anfang zufaellig gruen, weil
//     die vorlaeufigen return-Werte passen - das zaehlt noch nicht.
//
//  4. VORGEGEBEN (nicht veraendern): die Klasse Eintrag und in der
//     Rangliste der obere Block mit Attributen, Konstruktor, getAnzahl,
//     getEintrag, hinzufuegen, den Zaehlern und den beiden Werkzeugen
//          besser(a, b)     true, wenn a MEHR Punkte hat als b
//                           (zaehlt einen Vergleich)
//          vertausche(i, j) tauscht die Eintraege an Position i und j
//                           (zaehlt eine Vertauschung)
//     Warum ist vertausche schon fertig? Den Dreieckstausch mit
//     Hilfsvariable kennst du - er kommt im Papier-Warm-up dran. Hier
//     muessen die Zaehler bei allen exakt gleich zaehlen, sonst koennten
//     die Tests die Vergleichszahlen nicht pruefen.
//
//  5. ZAEHL-REGELN fuer Level 2.2 (sonst stimmen die Zahlen nicht):
//     - Sortiert wird ABSTEIGEND: Index 0 = Platz 1 = meiste Punkte.
//     - Eintraege beim Sortieren und Einfuegen NUR mit besser(...)
//       vergleichen, NIE direkt mit getPunkte().
//     - Die drei Sortierverfahren tauschen NUR mit vertausche(...).
//     - einfuegenSortiert SCHIEBT dagegen (eintraege[i] = eintraege[i - 1])
//       und benutzt vertausche nicht.
//     - Die Tests verraten dir die erwarteten Zahlen. Rechne sie vorher
//       mit einer Tracetabelle auf Papier nach - genau das kommt im
//       Abitur dran!
//
//  6. Die Testklassen (und die Hilfsklasse TestHilfe) darfst du NICHT
//     veraendern - sonst zaehlt der Test nicht. Du glaubst, ein Test ist
//     falsch? Melde ihn deiner Lehrkraft (Bug-Meldung).
//
//  7. Mit dem gruenen Startknopf oben laeuft das Hauptprogramm ganz unten
//     (eine kleine Highscore-Demo).
//
//  SPIELREGELN (wie im Abitur):
//  - Alle Attribute private, alle Methoden public (besser ist private).
//  - Schleifen ueber die Rangliste laufen von 0 bis anzahl - 1, NICHT
//    bis eintraege.length - 1: Dahinter stehen null-Eintraege.
//  - Zeichenketten IMMER mit equals vergleichen - nie mit ==.
//    (Die Online-IDE vergleicht mit == zwar den Inhalt, echtes Java
//    und das Abitur aber nicht!)
//  - Vor jedem Zugriff ueberlegen: Ist die Liste leer? Ist sie voll?
//    Kann hier null stehen?
// =====================================================================


// ---------------------------------------------------------------------
//  GERÜST – hier nichts veraendern
// ---------------------------------------------------------------------

// ---------------------------------------------------------------------
//  Klassenkarte Eintrag (eine Zeile der Highscore-Liste):
//
//      Eintrag
//      ---------------------------------------------------------------
//      - name: Zeichenkette
//      - punkte: Ganzzahl
//      - zeit: Ganzzahl                          // Spielzeit in Sekunden
//      ---------------------------------------------------------------
//      + c Eintrag(name: Zeichenkette, punkte: Ganzzahl, zeit: Ganzzahl)
//      + getName(): Zeichenkette
//      + getPunkte(): Ganzzahl
//      + getZeit(): Ganzzahl
//      + beschreibung(): Zeichenkette            // "Aria: 1200 Punkte (95 s)"
// ---------------------------------------------------------------------

class Eintrag {

    private String name;
    private int punkte;
    private int zeit;

    public Eintrag(String name, int punkte, int zeit) {
        this.name = name;
        this.punkte = punkte;
        this.zeit = zeit;
    }

    public String getName() {
        return name;
    }

    public int getPunkte() {
        return punkte;
    }

    public int getZeit() {
        return zeit;
    }

    public String beschreibung() {
        return name + ": " + punkte + " Punkte (" + zeit + " s)";
    }
}


// ---------------------------------------------------------------------
//  DEIN TEIL – hier arbeitest du!
// ---------------------------------------------------------------------
//  Klassenkarte Rangliste (Notation wie im Abitur):
//
//      Rangliste
//      ---------------------------------------------------------------
//      - eintraege: Reihung von Eintrag
//      - anzahl: Ganzzahl
//      - vergleiche: Ganzzahl
//      - vertauschungen: Ganzzahl
//      ---------------------------------------------------------------
//      + c Rangliste(kapazitaet: Ganzzahl)
//      + getAnzahl(): Ganzzahl
//      + getEintrag(i: Ganzzahl): Eintrag
//      + hinzufuegen(e: Eintrag): Wahrheitswert
//      + getVergleiche(): Ganzzahl
//      + getVertauschungen(): Ganzzahl
//      + zaehlerZuruecksetzen(): nichts
//      - besser(a: Eintrag, b: Eintrag): Wahrheitswert
//      + vertausche(i: Ganzzahl, j: Ganzzahl): nichts
//      + hoechstePunktzahl(): Ganzzahl                  Level 2.1
//      + besterEintrag(): Eintrag                       Level 2.1
//      + anzahlUeber(grenze: Ganzzahl): Ganzzahl        Level 2.1
//      + indexVon(name: Zeichenkette): Ganzzahl         Level 2.1
//      + durchschnitt(): Kommazahl                      Level 2.1
//      + hatDoppelteNamen(): Wahrheitswert              Level 2.1
//      + istSortiert(): Wahrheitswert                   Level 2.2
//      + selectionSort(): nichts                        Level 2.2
//      + insertionSort(): nichts                        Level 2.2
//      + bubbleSort(): nichts                           Level 2.2
//      + einfuegenSortiert(e: Eintrag): Wahrheitswert   Level 2.2
// ---------------------------------------------------------------------

class Rangliste {

    // ======== VORGEGEBEN – bis zur Linie "AB HIER ARBEITEST DU" nichts veraendern ========

    private Eintrag[] eintraege;
    private int anzahl;               // belegte Plaetze, zugleich naechster freier Index
    private int vergleiche;           // zaehlt die Aufrufe von besser(...)
    private int vertauschungen;       // zaehlt die Aufrufe von vertausche(...)

    // Leere Rangliste mit Platz fuer kapazitaet Eintraege.
    public Rangliste(int kapazitaet) {
        eintraege = new Eintrag[kapazitaet];
        anzahl = 0;
        vergleiche = 0;
        vertauschungen = 0;
    }

    public int getAnzahl() {
        return anzahl;
    }

    // Eintrag an Position i - oder null, wenn i kein gueltiger Index ist.
    public Eintrag getEintrag(int i) {
        if (i < 0 || i >= anzahl) {
            return null;
        }
        return eintraege[i];
    }

    // false, wenn e null ist oder die Liste voll ist. Sonst: e ans Ende,
    // anzahl erhoehen, true liefern. (Kennst du aus Welt 1: aufnehmen.)
    public boolean hinzufuegen(Eintrag e) {
        if (e == null || anzahl >= eintraege.length) {
            return false;
        }
        eintraege[anzahl] = e;
        anzahl++;
        return true;
    }

    public int getVergleiche() {
        return vergleiche;
    }

    public int getVertauschungen() {
        return vertauschungen;
    }

    public void zaehlerZuruecksetzen() {
        vergleiche = 0;
        vertauschungen = 0;
    }

    // besser(a: Eintrag, b: Eintrag): Wahrheitswert
    // true, wenn a MEHR Punkte hat als b - dann gehoert a weiter nach vorne.
    // Jeder Aufruf zaehlt einen Vergleich.
    // REGEL: Beim Sortieren und beim sortierten Einfuegen vergleichst du
    // Eintraege AUSSCHLIESSLICH mit besser(...) - nur so stimmen die Zaehler.
    private boolean besser(Eintrag a, Eintrag b) {
        vergleiche++;
        return a.getPunkte() > b.getPunkte();
    }

    // vertausche(i: Ganzzahl, j: Ganzzahl): nichts
    // Tauscht die Eintraege an den Positionen i und j (Dreieckstausch mit
    // Hilfsvariable) und zaehlt eine Vertauschung.
    // REGEL: Die drei Sortierverfahren vertauschen NUR mit vertausche(...).
    public void vertausche(int i, int j) {
        Eintrag hilf = eintraege[i];
        eintraege[i] = eintraege[j];
        eintraege[j] = hilf;
        vertauschungen++;
    }

    // ======== AB HIER ARBEITEST DU =============================================


    // ---------- Level 2.1: Standardbausteine (DS 13) ----------
    // Alle Schleifen laufen nur ueber die BELEGTEN Plaetze 0 .. anzahl - 1.
    // Dahinter stehen null-Eintraege!

    // Hoechste Punktzahl aller Eintraege. Leere Liste -> -1.
    // Achtung: Punkte koennen negativ sein (Strafpunkte).
    public int hoechstePunktzahl() {
        // TODO Level 2.1 · Basis
        return -1;
    }

    // Der Eintrag mit den meisten Punkten. Leere Liste -> null.
    // Bei Gleichstand der ERSTE.
    public Eintrag besterEintrag() {
        // TODO Level 2.1 · Basis
        return null;
    }

    // Anzahl der Eintraege mit MEHR als grenze Punkten.
    public int anzahlUeber(int grenze) {
        // TODO Level 2.1 · Basis
        return -1;
    }

    // Index des ERSTEN Eintrags mit genau diesem Namen, sonst -1.
    // Zeichenketten mit equals vergleichen!
    public int indexVon(String name) {
        // TODO Level 2.1 · Basis
        return -1;
    }

    // Durchschnitt der Punkte als Kommazahl. Leere Liste -> 0.0
    // Vorsicht: Ganzzahl / Ganzzahl rechnet ganzzahlig!
    public double durchschnitt() {
        // TODO Level 2.1 · Erweiterung
        return -1.0;
    }

    // true, wenn mindestens ein Name mehrfach vorkommt.
    // Tipp: zwei geschachtelte Schleifen - "jeder mit jedem".
    public boolean hatDoppelteNamen() {
        // TODO Level 2.1 · Experte
        return false;
    }


    // ---------- Level 2.2: Sortieren (DS 14) ----------
    // ABSTEIGEND nach Punkten: Platz 1 (Index 0) = meiste Punkte.
    // Vergleichen NUR mit besser(...), tauschen NUR mit vertausche(...).

    // true, wenn die Liste absteigend sortiert ist (gleiche Nachbarn erlaubt).
    // Leere Liste und Liste mit einem Eintrag -> true.
    // Hier direkt mit getPunkte() vergleichen, NICHT mit besser(...)
    // (istSortiert ist nur eine Kontrolle und soll nicht mitzaehlen).
    public boolean istSortiert() {
        // TODO Level 2.2 · Basis
        return false;
    }

    // Selectionsort mit MAXIMUM-Auswahl:
    // Fuer jede Position i: suche im Rest i .. anzahl - 1 den besten Eintrag
    // und tausche ihn an Position i - aber nur, wenn er nicht schon dort steht.
    public void selectionSort() {
        // TODO Level 2.2 · Basis
    }

    // Insertionsort: Der Eintrag an Position i wandert durch Vertauschen mit
    // dem linken Nachbarn nach links, solange er BESSER ist als dieser.
    // Gleich gute Eintraege werden nicht getauscht (stabil).
    public void insertionSort() {
        // TODO Level 2.2 · Basis
    }

    // Bubblesort: Benachbarte Eintraege vergleichen und tauschen, wenn der
    // rechte besser ist. Mit Abbruch: Blieb ein ganzer Durchlauf ohne
    // Vertauschung, ist die Liste fertig sortiert.
    public void bubbleSort() {
        // TODO Level 2.2 · Basis
    }

    // Fuegt e so ein, dass die (bereits absteigend sortierte) Liste sortiert
    // bleibt. false bei e == null oder voller Liste.
    // Schlechtere Eintraege werden von hinten her um eine Stelle nach rechts
    // GESCHOBEN (ohne vertausche!). Bei Gleichstand kommt e HINTER die
    // gleich guten Eintraege. Vergleichen mit besser(...).
    public boolean einfuegenSortiert(Eintrag e) {
        // TODO Level 2.2 · Erweiterung
        return false;
    }
}


// ---------------------------------------------------------------------
//  Level 2.3: Suche (DS 16) – auf Reihungen von Ganzzahlen
//
//      Suche
//      ---------------------------------------------------------------
//      + durchlaeufe: Ganzzahl                     (static, oeffentlich)
//      ---------------------------------------------------------------
//      + linear(r: Reihung von Ganzzahl, x: Ganzzahl): Ganzzahl
//      + binaer(r: Reihung von Ganzzahl, x: Ganzzahl): Ganzzahl
//      + einfuegeposition(r: Reihung von Ganzzahl, x: Ganzzahl): Ganzzahl
//
//  Alle Reihungen sind AUFSTEIGEND sortiert (kleinste Zahl vorne).
//  Jede Suche setzt zu Beginn durchlaeufe = 0 und erhoeht durchlaeufe in
//  jedem Schleifendurchlauf um 1. So kannst du nachzaehlen, wie viel
//  Arbeit eine Suche macht.
// ---------------------------------------------------------------------

class Suche {

    public static int durchlaeufe = 0;      // vorgegeben

    // Lineare Suche: Index des ERSTEN Vorkommens von x, sonst -1.
    // durchlaeufe = Zahl der geprueften Elemente.
    public static int linear(int[] r, int x) {
        // TODO Level 2.3 · Basis
        return -1;
    }

    // Binaere Suche, iterativ: lo = 0, hi = r.length - 1,
    // mid = (lo + hi) / 2. Liefert den Index EINES Vorkommens von x, sonst -1.
    // durchlaeufe = Zahl der Schleifendurchlaeufe.
    public static int binaer(int[] r, int x) {
        // TODO Level 2.3 · Basis
        return -1;
    }

    // Experte: kleinster Index i mit r[i] >= x - also die Stelle, an der man
    // x einfuegen muesste, damit r sortiert bleibt. Ist x groesser als alle
    // Elemente, ist das r.length. Leere Reihung -> 0.
    // Mit BINAERER Suche (und durchlaeufe zaehlen)!
    public static int einfuegeposition(int[] r, int x) {
        // TODO Level 2.3 · Experte
        return -1;
    }
}


// ---------------------------------------------------------------------
//  TESTS – hier nichts veraendern!
// ---------------------------------------------------------------------
//  Eine Testklasse pro Level. Die Stufe erkennst du am Anfang des
//  Testnamens:
//      basis_...        Basis       
//      erweiterung_...  Erweiterung 
//      experte_...      Experte     
//  Eine Stufe ist geschafft, wenn ALLE Tests mit diesem Anfang gruen sind.
// ---------------------------------------------------------------------

// Hilfsklasse fuer die Tests: baut Ranglisten und liest sie aus.
class TestHilfe {

    // Baut eine Rangliste mit der Kapazitaet kapazitaet aus den Namen und
    // Punkten (gleiche Position = gleicher Eintrag). Die Spielzeit ist fuer
    // die Tests unwichtig und betraegt einfach 100 + Position.
    public static Rangliste liste(int kapazitaet, String[] namen, int[] punkte) {
        Rangliste r = new Rangliste(kapazitaet);
        for (int i = 0; i < namen.length; i++) {
            r.hinzufuegen(new Eintrag(namen[i], punkte[i], 100 + i));
        }
        return r;
    }

    // Namen in Listenreihenfolge, z. B. "Cyra,Aria,Brann"
    public static String namen(Rangliste r) {
        String s = "";
        for (int i = 0; i < r.getAnzahl(); i++) {
            if (i > 0) {
                s = s + ",";
            }
            s = s + r.getEintrag(i).getName();
        }
        return s;
    }

    // Punkte in Listenreihenfolge, z. B. "1500,1200,800"
    public static String punkte(Rangliste r) {
        String s = "";
        for (int i = 0; i < r.getAnzahl(); i++) {
            if (i > 0) {
                s = s + ",";
            }
            s = s + r.getEintrag(i).getPunkte();
        }
        return s;
    }

    // Die Standardliste der Tests (Kapazitaet 10, also NICHT voll):
    //   Index:   0          1           2           3
    //            Aria 1200  Brann 800   Cyra 1500   Dorn 950
    public static Rangliste standard() {
        String[] namen = {"Aria", "Brann", "Cyra", "Dorn"};
        int[] punkte = {1200, 800, 1500, 950};
        return liste(10, namen, punkte);
    }
}


// ============== Level 2.1 – Standardbausteine (DS 13) =================

class L21StandardTest {

    @Test
    public void basis_hoechstePunktzahl() {
        Rangliste r = TestHilfe.standard();
        assertEquals(1500, r.hoechstePunktzahl(), "Standardliste (1200, 800, 1500, 950): hoechste Punktzahl ist 1500");
    }

    @Test
    public void basis_besterEintrag() {
        Rangliste r = TestHilfe.standard();
        assertTrue(r.besterEintrag() == r.getEintrag(2), "Standardliste: Cyra (1500 Punkte, Index 2) ist der beste Eintrag");
    }

    @Test
    public void basis_anzahlUeber() {
        Rangliste r = TestHilfe.standard();
        assertEquals(3, r.anzahlUeber(900), "Ueber 900 Punkte liegen Aria (1200), Cyra (1500) und Dorn (950): 3 Eintraege");
    }

    @Test
    public void basis_indexVon() {
        Rangliste r = TestHilfe.standard();
        assertEquals(1, r.indexVon("Brann"), "Brann steht an Index 1 - der Index beginnt bei 0");
        assertEquals(0, r.indexVon("Aria"), "Aria steht ganz vorne an Index 0");
    }

    @Test
    public void erweiterung_maximumAmAnfangUndAmEnde() {
        String[] n1 = {"Cyra", "Brann", "Dorn"};
        int[] p1 = {1500, 800, 950};
        Rangliste vorne = TestHilfe.liste(10, n1, p1);
        assertEquals(1500, vorne.hoechstePunktzahl(), "Das Maximum (1500) steht ganz vorne");
        assertTrue(vorne.besterEintrag() == vorne.getEintrag(0), "Der beste Eintrag (Cyra) steht ganz vorne an Index 0");

        String[] n2 = {"Brann", "Dorn", "Elin"};
        int[] p2 = {800, 950, 1600};
        Rangliste hinten = TestHilfe.liste(10, n2, p2);
        assertEquals(1600, hinten.hoechstePunktzahl(), "Das Maximum (1600) steht ganz hinten - laeuft deine Schleife bis anzahl - 1?");
        assertTrue(hinten.besterEintrag() == hinten.getEintrag(2), "Der beste Eintrag (Elin) steht ganz hinten - laeuft deine Schleife bis anzahl - 1?");
    }

    @Test
    public void erweiterung_anzahlUeber_grenzeGenau() {
        Rangliste r = TestHilfe.standard();
        assertEquals(1, r.anzahlUeber(1200), "Ueber 1200 liegt nur Cyra (1500) - 1200 selbst ist NICHT ueber 1200 (> statt >=)");
        assertEquals(0, r.anzahlUeber(1500), "Ueber 1500 liegt niemand");
        assertEquals(4, r.anzahlUeber(0), "Ueber 0 liegen alle 4 Eintraege");
    }

    @Test
    public void erweiterung_indexVon_letzterUndFehlender() {
        Rangliste r = TestHilfe.standard();
        assertEquals(3, r.indexVon("Dorn"), "Dorn steht ganz hinten an Index 3 - wird das letzte Element geprueft?");
        assertEquals(-1, r.indexVon("Zora"), "Zora steht nicht in der Liste: indexVon muss -1 liefern");
    }

    @Test
    public void erweiterung_indexVon_erstesVorkommen() {
        String[] namen = {"Brann", "Aria", "Cyra", "Aria"};
        int[] punkte = {800, 1200, 1500, 700};
        Rangliste r = TestHilfe.liste(10, namen, punkte);
        assertEquals(1, r.indexVon("Aria"), "Aria kommt an Index 1 und 3 vor: gesucht ist das ERSTE Vorkommen (Index 1)");
    }

    @Test
    public void erweiterung_durchschnitt() {
        String[] namen = {"Aria", "Brann", "Cyra", "Dorn"};
        int[] punkte = {100, 200, 250, 125};
        Rangliste r = TestHilfe.liste(10, namen, punkte);
        assertEquals(168.75, r.durchschnitt(), "(100 + 200 + 250 + 125) / 4 = 168.75 - Vorsicht: Ganzzahl / Ganzzahl rechnet ganzzahlig (168)!");
    }

    @Test
    public void erweiterung_leereListe() {
        Rangliste r = new Rangliste(5);
        assertEquals(-1, r.hoechstePunktzahl(), "Leere Liste: hoechstePunktzahl() muss -1 liefern");
        assertTrue(r.besterEintrag() == null, "Leere Liste: besterEintrag() muss null liefern");
        assertEquals(0, r.anzahlUeber(0), "Leere Liste: anzahlUeber muss 0 liefern");
        assertEquals(-1, r.indexVon("Aria"), "Leere Liste: indexVon muss -1 liefern - Vorsicht vor null-Eintraegen!");
        assertEquals(0.0, r.durchschnitt(), "Leere Liste: durchschnitt() muss 0.0 liefern - teile nie durch 0");
    }

    @Test
    public void experte_besterEintrag_gleichstand() {
        String[] namen = {"Brann", "Cyra", "Aria", "Elin"};
        int[] punkte = {800, 1500, 1200, 1500};
        Rangliste r = TestHilfe.liste(10, namen, punkte);
        assertTrue(r.besterEintrag() == r.getEintrag(1), "Cyra und Elin haben beide 1500 Punkte: bei Gleichstand muss der ERSTE (Cyra) geliefert werden (> statt >=)");
    }

    @Test
    public void experte_negativePunkte() {
        // Strafpunkte: Wer in eine Falle laeuft, kann negative Punkte haben.
        String[] namen = {"Brann", "Dorn", "Elin"};
        int[] punkte = {-50, -20, -80};
        Rangliste r = TestHilfe.liste(10, namen, punkte);
        assertEquals(-20, r.hoechstePunktzahl(), "Alle Punkte negativ (-50, -20, -80): Maximum ist -20 - starte nicht mit max = 0, sondern mit dem ersten Eintrag");
        assertTrue(r.besterEintrag() == r.getEintrag(1), "Alle Punkte negativ: Dorn (-20) ist der beste Eintrag - starte nicht mit 0 bzw. null");
        assertEquals(2, r.anzahlUeber(-60), "Ueber -60 liegen -50 und -20: 2 Eintraege");
        assertEquals(-50.0, r.durchschnitt(), "(-50 - 20 - 80) / 3 = -50.0");
    }

    @Test
    public void experte_volleListeUnveraendert() {
        // Kapazitaet 4, genau 4 Eintraege: die Reihung ist VOLL.
        String[] namen = {"Aria", "Brann", "Cyra", "Dorn"};
        int[] punkte = {1200, 800, 1500, 950};
        Rangliste r = TestHilfe.liste(4, namen, punkte);
        assertEquals(1500, r.hoechstePunktzahl(), "Volle Liste: hoechstePunktzahl() muss 1500 liefern (Index-Grenze anzahl - 1!)");
        assertTrue(r.besterEintrag() == r.getEintrag(2), "Volle Liste: Cyra ist der beste Eintrag");
        assertEquals(2, r.anzahlUeber(1000), "Volle Liste: ueber 1000 liegen Aria und Cyra");
        assertEquals(3, r.indexVon("Dorn"), "Volle Liste: Dorn steht an Index 3");
        assertEquals(1112.5, r.durchschnitt(), "Volle Liste: (1200 + 800 + 1500 + 950) / 4 = 1112.5");
        assertFalse(r.hatDoppelteNamen(), "Volle Liste: keine doppelten Namen");
        assertEquals("Aria,Brann,Cyra,Dorn", TestHilfe.namen(r), "Die Standardbausteine duerfen die Liste NICHT veraendern (Reihenfolge gleich lassen)");
        assertEquals(4, r.getAnzahl(), "Die Standardbausteine duerfen die Anzahl nicht veraendern");
    }

    @Test
    public void experte_indexVonMitEquals() {
        Rangliste r = TestHilfe.standard();
        String teil = "Cy";
        String gesucht = teil + "ra";
        assertEquals(2, r.indexVon(gesucht), "indexVon muss Zeichenketten mit equals vergleichen, nicht mit ==");
        assertEquals(-1, r.indexVon("Cyr"), "Gesucht ist der exakte Name: 'Cyr' ist nicht 'Cyra'");
        assertEquals(-1, r.indexVon("cyra"), "Gross- und Kleinschreibung zaehlt: 'cyra' ist nicht 'Cyra'");
    }

    @Test
    public void experte_hatDoppelteNamen_ja() {
        String[] namen = {"Aria", "Brann", "Cyra", "Aria"};
